(()=>{'use strict';const section=document.querySelector('.az-team-demo');if(!section)return;const cards=[...section.querySelectorAll('.az-mini')],mobile=matchMedia('(max-width:600px)'),hover=matchMedia('(hover:hover) and (min-width:601px)');const shade=document.createElement('div');shade.className='az-team-shade';shade.hidden=true;document.body.append(shade);let active=null,timer,locked=false,previousOverflow='';function close(restore=false){clearTimeout(timer);const previous=active;cards.forEach(c=>{c.classList.remove('open');c.querySelector('.az-bio').hidden=true;c.querySelector('.az-person').setAttribute('aria-expanded','false')});shade.hidden=true;if(locked){document.body.style.overflow=previousOverflow;locked=false}active=null;if(restore&&previous)previous.querySelector('.az-person').focus({preventScroll:true})}function open(c,focus=false){clearTimeout(timer);if(active!==c){close();active=c;c.classList.add('open');c.querySelector('.az-bio').hidden=false;c.querySelector('.az-person').setAttribute('aria-expanded','true')}if(mobile.matches){shade.hidden=false;if(!locked){previousOverflow=document.body.style.overflow;document.body.style.overflow='hidden';locked=true}}if(focus)c.querySelector('.az-close').focus({preventScroll:true})}cards.forEach(c=>{const b=c.querySelector('.az-person');b.addEventListener('click',()=>open(c,mobile.matches));c.addEventListener('pointerenter',e=>{if(e.pointerType==='mouse'&&hover.matches)open(c)});c.addEventListener('pointerleave',e=>{if(e.pointerType==='mouse'&&hover.matches)timer=setTimeout(()=>{if(!c.contains(document.activeElement))close()},200)});c.addEventListener('focusout',()=>{setTimeout(()=>{if(active===c&&!c.contains(document.activeElement)&&!c.matches(':hover'))close()},0)});c.querySelector('.az-close').onclick=()=>close(true);c.querySelector('.az-book').onclick=()=>close();});shade.onclick=()=>close(true);document.addEventListener('click',e=>{if(active&&!e.target.closest('.az-mini'))close()});document.addEventListener('keydown',e=>{if(!active)return;if(e.key==='Escape'){e.preventDefault();close(true)}else if(e.key==='Tab'&&mobile.matches){const controls=[...active.querySelector('.az-bio').querySelectorAll('button,a')],first=controls[0],last=controls[controls.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});mobile.addEventListener('change',()=>close());})();